"""Merge overlapping and touching integer intervals.

merge_intervals(intervals) -> list[list[int]]

Rules:
  * each interval is a pair [start, end] of ints
  * intervals that overlap OR merely touch (end == next start) are merged
  * output is sorted by start
  * the input sequence/objects are never mutated
  * a reversed pair (start > end) raises ValueError
"""

from __future__ import annotations

from typing import Iterable, List, Sequence


def _normalize(intervals: Iterable[Sequence[int]]) -> List[List[int]]:
    """Validate and copy the input into a fresh list of [start, end] lists."""
    if isinstance(intervals, (str, bytes)) or not isinstance(intervals, Iterable):
        raise TypeError("intervals must be an iterable of [start, end] pairs")

    cleaned: List[List[int]] = []
    for i, interval in enumerate(intervals):
        if isinstance(interval, (str, bytes)) or not isinstance(interval, (list, tuple)):
            raise TypeError(
                f"interval at index {i} must be a [start, end] pair, got {type(interval).__name__}"
            )
        if len(interval) != 2:
            raise ValueError(
                f"interval at index {i} must have exactly 2 elements, got {len(interval)}"
            )
        start, end = interval[0], interval[1]
        for name, value in (("start", start), ("end", end)):
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeError(
                    f"interval at index {i}: {name} must be an int, got {type(value).__name__}"
                )
        if start > end:
            raise ValueError(
                f"interval at index {i} is reversed: start {start} > end {end}"
            )
        cleaned.append([start, end])
    return cleaned


def merge_intervals(intervals: Iterable[Sequence[int]]) -> List[List[int]]:
    """Merge overlapping/touching integer intervals. Input is not mutated."""
    cleaned = _normalize(intervals)
    if not cleaned:
        return []

    cleaned.sort(key=lambda iv: (iv[0], iv[1]))

    merged: List[List[int]] = [cleaned[0][:]]
    for start, end in cleaned[1:]:
        last = merged[-1]
        # merge when overlapping or touching: start <= last_end
        if start <= last[1]:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged


if __name__ == "__main__":  # tiny demo
    print(merge_intervals([[1, 3], [2, 6], [8, 10], [15, 18]]))
    print(merge_intervals([[1, 4], [4, 5]]))
    print(merge_intervals([]))

