import copy
import unittest

from solution import merge_intervals


class TestMergeIntervals(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(merge_intervals([]), [])

    def test_single(self):
        self.assertEqual(merge_intervals([[1, 2]]), [[1, 2]])

    def test_overlap(self):
        self.assertEqual(
            merge_intervals([[1, 3], [2, 6], [8, 10], [15, 18]]),
            [[1, 6], [8, 10], [15, 18]],
        )

    def test_touching_endpoints_merge(self):
        self.assertEqual(merge_intervals([[1, 4], [4, 5]]), [[1, 5]])
        self.assertEqual(merge_intervals([[1, 2], [3, 4]]), [[1, 2], [3, 4]])
        self.assertEqual(merge_intervals([[5, 5], [5, 7]]), [[5, 7]])

    def test_unsorted_input_is_sorted_output(self):
        self.assertEqual(
            merge_intervals([[8, 10], [1, 3], [2, 6], [15, 18]]),
            [[1, 6], [8, 10], [15, 18]],
        )

    def test_contained_interval(self):
        self.assertEqual(merge_intervals([[1, 10], [2, 3]]), [[1, 10]])

    def test_touching_chain(self):
        self.assertEqual(merge_intervals([[1, 2], [2, 3], [3, 4]]), [[1, 4]])

    def test_duplicates(self):
        self.assertEqual(merge_intervals([[1, 3], [1, 3], [1, 3]]), [[1, 3]])

    def test_negative_and_zero(self):
        self.assertEqual(
            merge_intervals([[-5, -1], [-1, 0], [0, 4], [10, 10]]),
            [[-5, 4], [10, 10]],
        )

    def test_point_intervals(self):
        self.assertEqual(merge_intervals([[3, 3], [3, 3], [4, 4]]), [[3, 3], [4, 4]])
        self.assertEqual(merge_intervals([[3, 3], [3, 3]]), [[3, 3]])

    def test_does_not_mutate_input(self):
        intervals = [[5, 6], [1, 2], [2, 3]]
        before = copy.deepcopy(intervals)
        result = merge_intervals(intervals)
        self.assertEqual(intervals, before)
        self.assertEqual(result, [[1, 3], [5, 6]])
        # returned lists must be independent of the input
        result[0][0] = 999
        self.assertEqual(intervals, before)

    def test_does_not_mutate_input_tuples(self):
        intervals = [(5, 6), (1, 2)]
        before = copy.deepcopy(intervals)
        self.assertEqual(merge_intervals(intervals), [[1, 2], [5, 6]])
        self.assertEqual(intervals, before)

    def test_reversed_pair_raises(self):
        with self.assertRaises(ValueError):
            merge_intervals([[5, 1]])
        with self.assertRaises(ValueError):
            merge_intervals([[1, 2], [7, 3]])

    def test_reversed_detected_among_valid(self):
        with self.assertRaises(ValueError):
            merge_intervals([[1, 2], [10, 8], [3, 4]])

    def test_wrong_length_raises(self):
        with self.assertRaises(ValueError):
            merge_intervals([[1, 2, 3]])

    def test_wrong_type_raises(self):
        with self.assertRaises(TypeError):
            merge_intervals([[1, "2"]])
        with self.assertRaises(TypeError):
            merge_intervals([1, 2])

    def test_generator_input(self):
        gen = ([x, x + 5] for x in (0, 1, 2, 100))
        self.assertEqual(merge_intervals(gen), [[0, 7], [100, 105]])


if __name__ == "__main__":
    unittest.main(verbosity=2)

