from decimal import Decimal, InvalidOperation


def total(rows):
    """Sum decimal amounts exactly.

    Each entry is a string (or number) holding a signed decimal amount.
    Blank / whitespace-only entries are ignored. Malformed values raise ValueError.
    """
    result = Decimal("0")
    for row in rows:
        if row is None:
            continue
        if isinstance(row, str):
            text = row.strip()
            if not text:
                continue
        elif isinstance(row, Decimal):
            text = row
        elif isinstance(row, (int, float)):
            text = str(row)
        else:
            raise ValueError(f"malformed numeric value: {row!r}")
        try:
            value = Decimal(text)
        except (InvalidOperation, ValueError):
            raise ValueError(f"malformed numeric value: {row!r}")
        if not value.is_finite():
            raise ValueError(f"malformed numeric value: {row!r}")
        result += value
    return result

