"""Ledger totals with exact decimal arithmetic."""

from decimal import Decimal, InvalidOperation

__all__ = ["total"]


def _parse(value):
    """Return an exact Decimal for one row, or raise ValueError."""
    if isinstance(value, Decimal):
        amount = value
    elif isinstance(value, bool):
        raise ValueError(f"malformed numeric value: {value!r}")
    elif isinstance(value, int):
        amount = Decimal(value)
    elif isinstance(value, float):
        amount = Decimal(str(value))
    elif isinstance(value, str):
        text = value.strip()
        if not text:
            raise ValueError("malformed numeric value: blank row")
        try:
            amount = Decimal(text)
        except InvalidOperation:
            raise ValueError(f"malformed numeric value: {value!r}") from None
    else:
        raise ValueError(f"malformed numeric value: {value!r}")

    if not amount.is_finite():
        raise ValueError(f"malformed numeric value: {value!r}")
    return amount


def total(rows):
    """Sum ledger rows exactly with Decimal.

    Blank lines are skipped, signed amounts are accepted, and any
    malformed numeric value raises ValueError.
    """
    result = Decimal(0)
    for row in rows:
        if isinstance(row, str) and not row.strip():
            continue
        result += _parse(row)
    return result

