"""merge_intervals: merge overlapping and touching [start, end] intervals."""


def merge_intervals(intervals):
    """Merge overlapping/touching integer intervals.

    Args:
        intervals: iterable of [start, end] pairs, start <= end.

    Returns:
        New sorted list of merged [start, end] lists.

    Raises:
        ValueError: if any pair is reversed (start > end) or malformed.
        TypeError: if intervals is not a list/tuple.
    """
    if not isinstance(intervals, (list, tuple)):
        raise TypeError("intervals must be a list or tuple of pairs")

    prepared = []
    for pair in intervals:
        if not isinstance(pair, (list, tuple)) or len(pair) != 2:
            raise ValueError(f"malformed interval: {pair!r}")
        start, end = pair
        if not isinstance(start, int) or not isinstance(end, int) or isinstance(start, bool) or isinstance(end, bool):
            raise ValueError(f"interval bounds must be ints: {pair!r}")
        if start > end:
            raise ValueError(f"reversed interval: {pair!r}")
        prepared.append([start, end])  # copy: input never mutated

    if not prepared:
        return []

    prepared.sort(key=lambda p: (p[0], p[1]))

    merged = [prepared[0]]
    for start, end in prepared[1:]:
        last = merged[-1]
        # overlap OR touch (end + 1 == start)
        if start <= last[1] + 1:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])

    return merged

