        out = merge_intervals(data)
        self.assertEqual(out, sorted(out))
        self.assertEqual(out, [[0, 1], [5, 7], [10, 12]])

    def test_random_against_reference(self):
        def reference(intervals):
            # brute-force sweep on integer line
            pts = set()
            for s, e in intervals:
                pts.update(range(s, e + 1))
            if not pts:
                return []
            pts = sorted(pts)
            out = []
            start = prev = pts[0]
            for p in pts[1:]:
                if p == prev + 1:
                    prev = p
                else:
                    out.append([start, prev])
                    start = prev = p
            out.append([start, prev])
            return out

        rnd = random.Random(1234)
        for _ in range(500):
            n = rnd.randint(0, 8)
            data = []
            for _ in range(n):
                a = rnd.randint(-20, 20)
                b = rnd.randint(a, 20)
                data.append([a, b])
            self.assertEqual(merge_intervals(data), reference(data), data)


