from decimal import Decimal

from ledger import total


def raises(exc, fn, *args, **kwargs):
    try:
        fn(*args, **kwargs)
    except exc:
        return True
    raise AssertionError("%s not raised" % exc.__name__)


def test_exact_decimal_no_float_error():
    assert total(["0.1", "0.2"]) == Decimal("0.3")
    assert total(["0.1", "0.2"]) != Decimal(0.1) + Decimal(0.2)


def test_public_name_and_type():
    assert callable(total)
    assert isinstance(total(["1"]), Decimal)


def test_signed_amounts():
    assert total(["5", "-2", "+3"]) == Decimal("6")
    assert total(["-10", "-0.5"]) == Decimal("-10.5")


def test_blank_lines_ignored():
    assert total(["1", "", "   ", "\t", "2"]) == Decimal("3")
    assert total(["", "  "]) == Decimal("0")
    assert total([]) == Decimal("0")


def test_whitespace_padded_numbers():
    assert total([" 1.5 ", "\t-2.5\n"]) == Decimal("-1")


def test_malformed_raises_valueerror():
    for bad in ["abc", "1,000", "12abc", "$5", "1.2.3", "--3", "1 2"]:
        raises(ValueError, total, ["1", bad])


def test_non_finite_rejected():
    for bad in ["NaN", "Infinity", "-inf"]:
        raises(ValueError, total, [bad])


def test_large_precision():
    assert total(["9007199254740993", "1"]) == Decimal("9007199254740994")
